import type { IsoTimestamp, OrgId, UserId } from "./common";

/** What an API token is allowed to do. `read` tokens always act as a viewer. */
export type ApiTokenScope = "read" | "write";

/**
 * A personal API token. The secret and its hash never appear on this value —
 * the secret is returned once from `createApiToken`, and only the hash is stored.
 */
export interface ApiToken {
  readonly id: string;
  readonly orgId: OrgId;
  readonly userId: UserId;
  readonly name: string;
  readonly scope: ApiTokenScope;
  readonly prefix: string;
  readonly expiresAt: IsoTimestamp;
  readonly lastUsedAt: IsoTimestamp | null;
  readonly revokedAt: IsoTimestamp | null;
  readonly createdAt: IsoTimestamp;
}

import { z } from "zod";
import { orgIdSchema } from "./common";

export const createApiTokenSchema = z.object({
  orgId: orgIdSchema,
  name: z.string().trim().min(1).max(80),
  scope: z.enum(["read", "write"]),
  expiresInDays: z.number().int().min(1).max(365),
});

export type CreateApiTokenInput = z.input<typeof createApiTokenSchema>;

import { index, sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import { idColumn, tenantColumns, timestampColumns } from "./_shared";

/**
 * Personal API tokens. `token_hash` is the only form of the secret that is
 * stored; the raw token is shown once at creation and never written down.
 */
export const apiTokens = sqliteTable(
  "api_tokens",
  {
    id: idColumn(),
    ...tenantColumns,
    userId: text("user_id").notNull(),
    name: text("name").notNull(),
    scope: text("scope", { enum: ["read", "write"] }).notNull(),
    prefix: text("prefix").notNull(),
    tokenHash: text("token_hash").notNull(),
    expiresAt: text("expires_at").notNull(),
    lastUsedAt: text("last_used_at"),
    revokedAt: text("revoked_at"),
    ...timestampColumns,
  },
  (table) => [
    uniqueIndex("api_tokens_token_idx").on(table.tokenHash),
    index("api_tokens_org_user_idx").on(table.orgId, table.userId),
  ],
);

export type ApiTokenRow = typeof apiTokens.$inferSelect;
export type NewApiTokenRow = typeof apiTokens.$inferInsert;

/**
 * Personal API tokens. Reads that serve a request are scoped by `orgId`;
 * the hash lookup is the exception, because the token itself is the credential.
 */
import { and, count, desc, eq, gt, isNull } from "drizzle-orm";
import { newId } from "@/lib/id";
import { apiTokens, getDb } from "@/server/db";
import { orgPredicate } from "./base-repository";
import { toApiToken } from "./_mappers";
import type { ApiToken, ApiTokenScope } from "@/types/api-token";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";

export interface InsertApiTokenInput {
  readonly orgId: OrgId;
  readonly userId: UserId;
  readonly name: string;
  readonly scope: ApiTokenScope;
  readonly prefix: string;
  readonly tokenHash: string;
  readonly expiresAt: IsoTimestamp;
  readonly createdAt: IsoTimestamp;
}

/**
 * Inserts a token when the user is under `maxUsable` live tokens in the org.
 * The count and the insert run without an await between them, so two creates
 * cannot both observe the same count.
 */
export async function insertApiToken(
  input: InsertApiTokenInput,
  maxUsable: number,
): Promise<ApiToken> {
  const db = getDb();
  const usable = db
    .select({ value: count() })
    .from(apiTokens)
    .where(
      and(
        orgPredicate(apiTokens.orgId, input.orgId),
        eq(apiTokens.userId, input.userId),
        isNull(apiTokens.revokedAt),
        gt(apiTokens.expiresAt, input.createdAt),
      ),
    )
    .get();

  if ((usable?.value ?? 0) >= maxUsable) {
    throw new Error(
      "A user may hold at most 5 usable API tokens per organization",
    );
  }

  const row = db
    .insert(apiTokens)
    .values({
      id: newId(),
      orgId: input.orgId,
      userId: input.userId,
      name: input.name,
      scope: input.scope,
      prefix: input.prefix,
      tokenHash: input.tokenHash,
      expiresAt: input.expiresAt,
      lastUsedAt: null,
      revokedAt: null,
      createdAt: input.createdAt,
      updatedAt: input.createdAt,
    })
    .returning()
    .get();

  return toApiToken(row);
}

/** Every token the user holds in the org, revoked and expired included, newest first. */
export async function listApiTokens(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ApiToken[]> {
  const rows = getDb()
    .select()
    .from(apiTokens)
    .where(
      and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.userId, userId)),
    )
    .orderBy(desc(apiTokens.createdAt), desc(apiTokens.id))
    .all();

  return rows.map(toApiToken);
}

export async function findApiTokenById(
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)))
    .get();

  return row ? toApiToken(row) : null;
}

/**
 * Authentication runs before an actor exists, so the hash is the credential
 * and carries the tenant with it — the same exception invitations make.
 */
export async function findApiTokenByHash(
  tokenHash: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(eq(apiTokens.tokenHash, tokenHash))
    .get();

  return row ? toApiToken(row) : null;
}

/**
 * Sets `revokedAt` only when the token is not already revoked. Returns null
 * when the row is missing or was already revoked, so the caller can avoid
 * writing a second audit entry.
 */
export async function markRevoked(
  orgId: OrgId,
  tokenId: string,
  revokedAt: IsoTimestamp,
): Promise<ApiToken | null> {
  const row = getDb()
    .update(apiTokens)
    .set({ revokedAt, updatedAt: revokedAt })
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.id, tokenId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .returning()
    .get();

  return row ? toApiToken(row) : null;
}

export async function touchLastUsedAt(
  orgId: OrgId,
  tokenId: string,
  lastUsedAt: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(apiTokens)
    .set({ lastUsedAt, updatedAt: lastUsedAt })
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)))
    .run();
}

