/**
 * Personal API tokens. The secret is returned once, at creation; only its hash
 * is stored. Creation and revocation are published as domain events and the
 * audit log records them from the activity listener.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, hashToken, subscribe
 */
import { emit, subscribe } from "@/lib/event-bus";
import { hashToken, randomToken } from "@/lib/hash";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import { createApiTokenSchema } from "@/schemas/api-token";
import * as apiTokenRepo from "@/server/repositories/api-token-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { toIsoTimestamp } from "@/types/common";
import { orgResource, requireFound } from "./_support";
import { resolveActor } from "./member-service";
import type { CreateApiTokenInput } from "@/schemas/api-token";
import type { ApiToken } from "@/types/api-token";
import type { OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";

/** How many usable (not revoked, not expired) tokens one user may hold per org. */
const MAX_USABLE_TOKENS = 5;

/** Bytes of entropy after the `tfk_` prefix. Matches the session token width. */
const TOKEN_BYTES = 32;

/** `prefix` is the first this-many characters of the secret, including `tfk_`. */
const PREFIX_LENGTH = 12;

const MS_PER_DAY = 24 * 60 * 60 * 1000;

export async function createApiToken(
  actor: Actor,
  input: CreateApiTokenInput,
): Promise<{ token: string; apiToken: ApiToken }> {
  const parsed = createApiTokenSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);

  if (parsed.scope === "write") {
    assertCan(actor, "api_token:create_write", orgResource(parsed.orgId));
  }

  const createdAtDate = new Date();
  const createdAt = toIsoTimestamp(createdAtDate);
  const expiresAt = toIsoTimestamp(
    new Date(createdAtDate.getTime() + parsed.expiresInDays * MS_PER_DAY),
  );
  const token = `tfk_${randomToken(TOKEN_BYTES)}`;

  const apiToken = await apiTokenRepo.insertApiToken(
    {
      orgId: parsed.orgId,
      userId: actor.userId,
      name: parsed.name,
      scope: parsed.scope,
      prefix: token.slice(0, PREFIX_LENGTH),
      tokenHash: hashToken(token),
      expiresAt,
      createdAt,
    },
    MAX_USABLE_TOKENS,
  );

  await emit("api_token.created", {
    orgId: parsed.orgId,
    actorId: actor.userId,
    occurredAt: createdAt,
    tokenId: apiToken.id,
    userId: actor.userId,
    name: apiToken.name,
    scope: apiToken.scope,
  });

  return { token, apiToken };
}

export async function listApiTokens(
  actor: Actor,
  orgId: OrgId,
  userId?: UserId,
): Promise<readonly ApiToken[]> {
  assertOrgScope(actor, orgId);
  const targetUserId = userId ?? actor.userId;

  if (targetUserId !== actor.userId) {
    assertCan(actor, "api_token:manage", orgResource(orgId));
  }

  return apiTokenRepo.listApiTokens(orgId, targetUserId);
}

export async function revokeApiToken(
  actor: Actor,
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken> {
  assertOrgScope(actor, orgId);

  const existing = requireFound(
    await apiTokenRepo.findApiTokenById(orgId, tokenId),
    "ApiToken",
    tokenId,
  );

  if (existing.userId !== actor.userId) {
    assertCan(actor, "api_token:manage", orgResource(orgId));
  }

  if (existing.revokedAt !== null) return existing;

  const revoked = await apiTokenRepo.markRevoked(
    orgId,
    tokenId,
    toIsoTimestamp(new Date()),
  );
  if (!revoked) {
    return requireFound(
      await apiTokenRepo.findApiTokenById(orgId, tokenId),
      "ApiToken",
      tokenId,
    );
  }

  await publishRevoked(orgId, actor.userId, revoked);
  return revoked;
}

/**
 * Resolves the actor a token stands for. `null` means the credential is not
 * usable: unknown, revoked, expired, the member is gone, or the org is deleted.
 * A failed call leaves the row untouched; a successful one stamps `lastUsedAt`.
 */
export async function authenticateApiToken(
  token: string,
): Promise<Actor | null> {
  const row = await apiTokenRepo.findApiTokenByHash(hashToken(token));
  if (!row || row.revokedAt !== null) return null;

  const now = toIsoTimestamp(new Date());
  if (row.expiresAt <= now) return null;

  const org = await orgRepo.findOrgById(row.orgId);
  if (!org || org.archivedAt !== null) return null;

  const member = await resolveActor(row.userId, row.orgId);
  if (!member) return null;

  await apiTokenRepo.touchLastUsedAt(row.orgId, row.id, now);

  return {
    userId: row.userId,
    orgId: row.orgId,
    role: row.scope === "read" ? "viewer" : member.role,
  };
}

/**
 * When a member leaves an organization, every still-live token of theirs in
 * that organization is revoked and audited as the remover. Already-revoked
 * tokens keep their original timestamp. Other organizations are untouched
 * because the query is scoped to the event's org.
 */
export function registerApiTokenListeners(): Unsubscribe {
  return subscribe("member.removed", async (payload) => {
    const tokens = await apiTokenRepo.listApiTokens(
      payload.orgId,
      payload.userId,
    );

    for (const token of tokens) {
      if (token.revokedAt !== null) continue;

      const revoked = await apiTokenRepo.markRevoked(
        payload.orgId,
        token.id,
        toIsoTimestamp(new Date()),
      );
      if (!revoked) continue;

      await publishRevoked(payload.orgId, payload.actorId, revoked);
    }
  });
}

async function publishRevoked(
  orgId: OrgId,
  actorId: UserId | null,
  token: ApiToken,
): Promise<void> {
  await emit("api_token.revoked", {
    orgId,
    actorId,
    occurredAt: token.revokedAt ?? toIsoTimestamp(new Date()),
    tokenId: token.id,
    userId: token.userId,
    name: token.name,
  });
}

