    expiresInDays: 1,
  });
} catch (error) {
  zodThrew = error instanceof ZodError;
}
assert(zodThrew, "bad scope ZodError");

zodThrew = false;
try {
  await createApiToken(viewer, {
    orgId: tenant.org.id,
    name: "ok",
    scope: "read",
    expiresInDays: 1.5,
  });
} catch (error) {
  zodThrew = error instanceof ZodError;
}
assert(zodThrew, "fractional days ZodError");

zodThrew = false;
try {
  await createApiToken(viewer, {
    orgId: tenant.org.id,
    name: "ok",
    scope: "read",
    expiresInDays: 366,
  });
} catch (error) {
  zodThrew = error instanceof ZodError;
}
assert(zodThrew, "366 ZodError");

const beforeInvalid = await listApiTokens(viewer, tenant.org.id);
assert(beforeInvalid.length === 1, "invalid input stored nothing");

let scopeThrew = false;
try {
  await createApiToken(viewer, { ...input, name: "write-me", scope: "write" });
} catch (error) {
  scopeThrew = error instanceof TenantScopeError;
  assert(!(error instanceof PermissionDeniedError), "wrong org is tenant not permission");
}
try {
  await createApiToken(viewer, {
    orgId: other.org.id,
    name: "nope",
    scope: "read",
    expiresInDays: 1,
  });
} catch (error) {
  scopeThrew = error instanceof TenantScopeError;
}
assert(scopeThrew, "cross tenant TenantScopeError");

let denied = false;
try {
  await createApiToken(viewer, {
    orgId: tenant.org.id,
    name: "writer",
    scope: "write",
    expiresInDays: 3,
  });
} catch (error) {
  denied = error instanceof PermissionDeniedError;
}
assert(denied, "viewer write is PermissionDeniedError");

const write = await createApiToken(member, {
  orgId: tenant.org.id,
  name: "writer",
  scope: "write",
  expiresInDays: 3,
});
assert(write.apiToken.scope === "write", "member can create write");

const listed = await listApiTokens(viewer, tenant.org.id);
assert(listed.length === 1, "viewer sees only own");
assert(listed[0]!.id === created.apiToken.id, "own token");

denied = false;
try {
  await listApiTokens(member, tenant.org.id, viewer.userId);
} catch (error) {
  denied = error instanceof PermissionDeniedError;
}
assert(denied, "member cannot list others");

const adminList = await listApiTokens(admin, tenant.org.id, viewer.userId);
assert(adminList.length === 1, "admin lists others");

denied = false;
try {
  await revokeApiToken(member, tenant.org.id, created.apiToken.id);
} catch (error) {
  denied = error instanceof PermissionDeniedError;
}
assert(denied, "member cannot revoke others");

let missing = false;
try {
  await revokeApiToken(viewer, tenant.org.id, "01HZZZNOTEXISTTOKEN12345678");
} catch (error) {
  missing = error instanceof NotFoundError;
}
assert(missing, "missing token is NotFoundError");

scopeThrew = false;
try {
  await revokeApiToken(viewer, other.org.id, created.apiToken.id);
} catch (error) {
  scopeThrew = error instanceof TenantScopeError;
}
assert(scopeThrew, "revoke other org is tenant error");

const authedRead = await authenticateApiToken(created.token);
assert(authedRead?.role === "viewer", "read token is viewer");
assert(authedRead?.userId === viewer.userId, "read user");
assert(authedRead?.orgId === tenant.org.id, "read org");

const afterUse = await listApiTokens(viewer, tenant.org.id);
assert(afterUse[0]!.lastUsedAt !== null, "lastUsedAt set");

const authedWrite = await authenticateApiToken(write.token);
assert(authedWrite?.role === "member", "write token uses member role");

const viewerMember = await memberRepo.findMember(tenant.org.id, viewer.userId);
assert(viewerMember, "viewer member");
await updateMemberRole(owner, {
  orgId: tenant.org.id,
  memberId: viewerMember.id,
  role: "admin",
});
const stillViewer = await authenticateApiToken(created.token);
assert(stillViewer?.role === "viewer", "read token stays viewer after promotion");

const memberRow = await memberRepo.findMember(tenant.org.id, member.userId);
assert(memberRow, "member row");
await updateMemberRole(owner, {
  orgId: tenant.org.id,
  memberId: memberRow.id,
  role: "admin",
});
const promoted = await authenticateApiToken(write.token);
assert(promoted?.role === "admin", "write token follows promotion");
await updateMemberRole(owner, {
  orgId: tenant.org.id,
  memberId: memberRow.id,
  role: "viewer",
});
const demoted = await authenticateApiToken(write.token);
assert(demoted?.role === "viewer", "write token follows demotion");
await updateMemberRole(owner, {
  orgId: tenant.org.id,
  memberId: memberRow.id,
  role: "member",
});

assert((await authenticateApiToken("tfk_not-a-real-token")) === null, "unknown is null");

const usedBeforeRevoke = (await listApiTokens(viewer, tenant.org.id))[0]!.lastUsedAt;
const revoked = await revokeApiToken(viewer, tenant.org.id, created.apiToken.id);
assert(revoked.revokedAt !== null, "revokedAt set");
const again = await revokeApiToken(viewer, tenant.org.id, created.apiToken.id);
assert(again.revokedAt === revoked.revokedAt, "second revoke keeps original");

const revokeAudits = await activityRepo.listActivity({
  orgId: tenant.org.id,
  action: ["api_token.revoked"],
  subjectKind: "api_token",
  limit: 25,
  cursor: null,
});
assert(revokeAudits.items.length === 1, "one revoke audit, not two");
assert(revokeAudits.items[0]!.actorId === viewer.userId, "revoker is actor");
assert(
  !JSON.stringify(revokeAudits.items).includes(created.token),
  "revoke audit has no secret",
);
assert((await authenticateApiToken(created.token)) === null, "revoked token fails");
const afterFailed = (await listApiTokens(viewer, tenant.org.id))[0]!;
assert(afterFailed.lastUsedAt === usedBeforeRevoke, "failed auth does not touch lastUsed");

// expired token
const expiring = await createApiToken(owner, {
  orgId: tenant.org.id,
  name: "short",
  scope: "read",
  expiresInDays: 1,
});
getDb()
  .update(apiTokens)
  .set({ expiresAt: toIsoTimestamp(new Date()) })
  .where(eq(apiTokens.id, expiring.apiToken.id))
  .run();
assert((await authenticateApiToken(expiring.token)) === null, "expired at exactly expiresAt");
const expiredRow = await listApiTokens(owner, tenant.org.id);
const expiredToken = expiredRow.find((row) => row.id === expiring.apiToken.id);
assert(expiredToken?.lastUsedAt === null, "expired auth changes nothing");

// allowance: 5 usable, revoked and expired do not count, per user
const holder = admin;
const made: string[] = [];
for (let i = 0; i < 4; i += 1) {
  const row = await createApiToken(holder, {
    orgId: tenant.org.id,
    name: `t${i}`,
    scope: "read",
    expiresInDays: 10,
  });
  made.push(row.apiToken.id);
}
// holder has 4. owner has expired + maybe others. viewer has revoked.
// sixth for holder: create one more (5th) then 6th fails.
const fifth = await createApiToken(holder, {
  orgId: tenant.org.id,
  name: "fifth",
  scope: "read",
  expiresInDays: 10,
});
let limited = false;
try {
  await createApiToken(holder, {
    orgId: tenant.org.id,
    name: "sixth",
    scope: "read",
    expiresInDays: 10,
  });
} catch (error) {
  limited = error instanceof Error;
}
assert(limited, "sixth throws");
const holderTokens = await listApiTokens(holder, tenant.org.id);
assert(holderTokens.length === 5, "sixth stored nothing");
assert(!holderTokens.some((row) => row.name === "sixth"), "no sixth name");

await revokeApiToken(holder, tenant.org.id, fifth.apiToken.id);
const afterRevokeSlot = await createApiToken(holder, {
  orgId: tenant.org.id,
  name: "after-revoke",
  scope: "read",
  expiresInDays: 2,
});
assert(afterRevokeSlot.apiToken.name === "after-revoke", "revoked frees a slot");

// expire one of the remaining usable to free a slot, after filling to 5 again
const filler = await createApiToken(holder, {
  orgId: tenant.org.id,
  name: "filler",
  scope: "read",
  expiresInDays: 4,
});
let fullAgain = false;
try {
  await createApiToken(holder, {
    orgId: tenant.org.id,
    name: "overflow",
    scope: "write",
    expiresInDays: 4,
  });
} catch {
  fullAgain = true;
}
assert(fullAgain, "full again");
getDb()
  .update(apiTokens)
  .set({ expiresAt: "2000-01-01T00:00:00.000Z" })
  .where(eq(apiTokens.id, filler.apiToken.id))
  .run();
const afterExpire = await createApiToken(holder, {
  orgId: tenant.org.id,
  name: "after-expire",
  scope: "write",
  expiresInDays: 4,
});
assert(afterExpire.apiToken.name === "after-expire", "expired frees a slot");

// other user still has their own allowance
const otherUserToken = await createApiToken(owner, {
  orgId: tenant.org.id,
  name: "owner-own",
  scope: "write",
  expiresInDays: 9,
});
assert(otherUserToken.apiToken.userId === owner.userId, "separate allowance");

// suspended member cannot authenticate, and nothing changes
const suspendTarget = await createApiToken(owner, {
  orgId: tenant.org.id,
  name: "suspend-me",
  scope: "write",
  expiresInDays: 5,
});
getDb()
  .update(apiTokens)
  .set({ lastUsedAt: null })
  .where(eq(apiTokens.id, suspendTarget.apiToken.id))
  .run();
const { members } = await import(
  "../private/tmp/bench-scratch/f6161d8e-7b93-494a-aff1-845a7e3bbe58/src/server/db/schema/members"
);
const ownerMember = await memberRepo.findMember(tenant.org.id, owner.userId);
assert(ownerMember, "owner member");
getDb()
  .update(members)
  .set({ status: "suspended" })
  .where(eq(members.id, ownerMember.id))
  .run();
assert((await authenticateApiToken(suspendTarget.token)) === null, "suspended fails");
const suspendedListed = (await listApiTokens(admin, tenant.org.id, owner.userId)).find(
  (row) => row.id === suspendTarget.apiToken.id,
);
assert(suspendedListed?.lastUsedAt === null, "suspended changes nothing");
assert(suspendedListed?.revokedAt === null, "suspended does not revoke");
getDb()
  .update(members)
  .set({ status: "active" })
  .where(eq(members.id, ownerMember.id))
  .run();

// deleted org
const orgToken = await createApiToken(member, {
  orgId: tenant.org.id,
  name: "org-gone",
  scope: "read",
  expiresInDays: 6,
});
await orgRepo.archiveOrg(tenant.org.id);
assert((await authenticateApiToken(orgToken.token)) === null, "deleted org fails");
const orgListed = (await listApiTokens(member, tenant.org.id)).find(
  (row) => row.id === orgToken.apiToken.id,
);
assert(orgListed?.lastUsedAt === null, "deleted org changes nothing");

// member removal revokes live tokens (including expired) and audits as remover.
// Restore nothing; org is archived but removal does not check org liveness.
// Use the other tenant so the org is live.
unregisterEventHandlers();
registerEventHandlers();

const removedUser = other.actors.member;
const kept = await createApiToken(removedUser, {
  orgId: other.org.id,
  name: "keep-revoked",
  scope: "read",
  expiresInDays: 8,
});
await revokeApiToken(removedUser, other.org.id, kept.apiToken.id);
const originalRevokedAt = (
  await listApiTokens(removedUser, other.org.id)
).find((row) => row.id === kept.apiToken.id)!.revokedAt;

const live = await createApiToken(removedUser, {
  orgId: other.org.id,
  name: "live",
  scope: "write",
  expiresInDays: 8,
});
const expiredToo = await createApiToken(removedUser, {
  orgId: other.org.id,
  name: "expired-too",
  scope: "read",
  expiresInDays: 8,
});
getDb()
  .update(apiTokens)
  .set({ expiresAt: "2000-01-01T00:00:00.000Z" })
  .where(eq(apiTokens.id, expiredToo.apiToken.id))
  .run();

// token in a different org for the same user must survive
const secondOrg = await orgRepo.insertOrg(
  { name: "Side", slug: "side-org", plan: "growth" },
  removedUser.userId,
);
await memberRepo.insertMember(secondOrg.id, removedUser.userId, "member", null);
const elsewhere = await createApiToken(
  { userId: removedUser.userId, orgId: secondOrg.id, role: "member" },
  { orgId: secondOrg.id, name: "elsewhere", scope: "read", expiresInDays: 4 },
);

const removedMember = await memberRepo.findMember(other.org.id, removedUser.userId);
assert(removedMember, "removed member row");
const auditsBefore = (
  await activityRepo.listActivity({
    orgId: other.org.id,
    action: ["api_token.revoked"],
    limit: 50,
    cursor: null,
  })
).items.length;

await removeMember(other.actors.owner, {
  orgId: other.org.id,
  memberId: removedMember.id,
});

const afterRemoval = await listApiTokens(
  other.actors.owner,
  other.org.id,
  removedUser.userId,
);
const keptRow = afterRemoval.find((row) => row.id === kept.apiToken.id);
const liveRow = afterRemoval.find((row) => row.id === live.apiToken.id);
const expiredRow2 = afterRemoval.find((row) => row.id === expiredToo.apiToken.id);
assert(keptRow?.revokedAt === originalRevokedAt, "already revoked unchanged");
assert(liveRow?.revokedAt !== null, "live revoked on removal");
assert(expiredRow2?.revokedAt !== null, "expired revoked on removal");

const elsewhereRow = (
  await listApiTokens(
    { userId: removedUser.userId, orgId: secondOrg.id, role: "member" },
    secondOrg.id,
  )
).find((row) => row.id === elsewhere.apiToken.id);
assert(elsewhereRow?.revokedAt === null, "other org untouched");

const removalAudits = await activityRepo.listActivity({
  orgId: other.org.id,
  action: ["api_token.revoked"],
  limit: 50,
  cursor: null,
});
const fresh = removalAudits.items.filter(
  (row) => row.subjectId === live.apiToken.id || row.subjectId === expiredToo.apiToken.id,
);
assert(fresh.length === 2, "two new revoke audits");
assert(
  fresh.every((row) => row.actorId === other.actors.owner.userId),
  "remover is the audit actor",
);
assert(
  !removalAudits.items.some((row) => row.subjectId === kept.apiToken.id && row !== kept),
  "no second audit for already revoked",
);
const keptAudits = removalAudits.items.filter((row) => row.subjectId === kept.apiToken.id);
assert(keptAudits.length === 1, "original revoke audit only");

const newest = await listApiTokens(holder, tenant.org.id);
const names = newest.map((row) => row.createdAt);
const sorted = [...names].sort((a, b) => (a < b ? 1 : a > b ? -1 : 0));
assert(JSON.stringify(names) === JSON.stringify(sorted), "newest first");

console.log("ALL CHECKS PASSED");
unregisterEventHandlers();
cleanup();
